progressive_examples.raw_code:
// Khai báo hàm tính tiền mặt hàng (Function Declaration)
function calculateItemTotal(price, quantity) {
  const total = price * quantity;
  return total;
}

// Gọi hàm thực thi
const itemTotal = calculateItemTotal(25000, 4);
console.log("Tổng tiền sản phẩm:", itemTotal);

// Khai báo hàm biểu thức (Function Expression) tính số tiền thanh toán
const calculateFinalPayment = function(subtotal, discountRate) {
  const discountAmount = subtotal * discountRate;
  const finalPayment = subtotal - discountAmount;
  return finalPayment;
};

// Gọi hàm tính tiền cho hóa đơn
const subtotal = 500000;
const discountRate = 0.1; // Giảm giá 10%
const amountToPay = calculateFinalPayment(subtotal, discountRate);

console.log("Số tiền khách phải trả:", amountToPay);

// Hàm tính toán hóa đơn siêu thị đầy đủ
function processSupermarketReceipt(unitPrice, quantity, discountRate) {
  // Kiểm tra dữ liệu đầu vào hợp lệ
  if (unitPrice <= 0 || quantity <= 0) {
    return 0;
  }

  const subtotal = unitPrice * quantity;
  const discountAmount = subtotal * discountRate;
  const finalPayment = subtotal - discountAmount;

  return finalPayment;
}

// Trường hợp dữ liệu hợp lệ
const validInvoice = processSupermarketReceipt(120000, 3, 0.05);
console.log("Hóa đơn hợp lệ:", validInvoice);

// Trường hợp số lượng không hợp lệ (bằng 0)
const invalidInvoice = processSupermarketReceipt(120000, 0, 0.05);
console.log("Hóa đơn không hợp lệ:", invalidInvoice);

